function createDynamicApartmentManifest(input2) {
  const flatsCount = input2.flatsPerFloor;
  const units = input2.units && input2.units.length === flatsCount ? [...input2.units] : Array.from({ length: flatsCount }, (_, i) => ({
    unitIndex: i + 1,
    bhkType: "3BHK",
    targetCarpetSqFt: 1100,
    attachedBathCount: 2,
    hasUtilityBalcony: true
  }));
  return {
    plotWidthMm: input2.plotWidthMm,
    plotDepthMm: input2.plotDepthMm,
    lotAllotmentMode: input2.lotAllotmentMode ?? "STATUTORY_SETBACK_100_PERCENT",
    flatsPerFloor: flatsCount,
    units,
    jurisdiction: input2.jurisdiction ?? "pune_pmc",
    northAngleDeg: input2.northAngleDeg ?? 0,
    buildingTypology: input2.buildingTypology ?? BuildingTypologyCategory.ResidentialApartment
  };
}

