    y: Math.min(...r.boundary.points.map((pt) => pt.y)),
    w: Math.max(...r.boundary.points.map((pt) => pt.x)) - Math.min(...r.boundary.points.map((pt) => pt.x)),
    h: Math.max(...r.boundary.points.map((pt) => pt.y)) - Math.min(...r.boundary.points.map((pt) => pt.y))
