function calculateMeanLuminance(imageBuffer) {
  if (!imageBuffer || imageBuffer.length < 1e3) return 0;
  let sumLuma = 0;
  let count = 0;
  const sampleStep = Math.max(1, Math.floor(imageBuffer.length / 8e3));
  for (let i = 100; i < imageBuffer.length - 4; i += sampleStep) {
    const r = imageBuffer[i];
    const g = imageBuffer[i + 1];
    const b = imageBuffer[i + 2];
    const luma = 0.299 * r + 0.587 * g + 0.114 * b;
    sumLuma += luma;
    count++;
  }
  return count > 0 ? sumLuma / count : 0;
}
function calculateColorVariance(imageBuffer) {
  if (!imageBuffer || imageBuffer.length < 1e3) return 0;
  let sum = 0;
  let sumSq = 0;
  const sampleStep = Math.max(1, Math.floor(imageBuffer.length / 5e3));
  let count = 0;
  for (let i = 100; i < imageBuffer.length; i += sampleStep) {
    const val = imageBuffer[i];
    sum += val;
    sumSq += val * val;
    count++;
  }
  const mean = sum / count;
  return sumSq / count - mean * mean;
}
